// Cloudinary settings in .env. The secret is NOT in this script: paste it yourself.
// ---------------------------------------------------------------------------
const CLOUDINARY_BLOCK = `
# Cloudinary, for photo uploads (cloudinary.com → Settings → API Keys)
CLOUDINARY_CLOUD_NAME=dbcdsonhz
CLOUDINARY_API_KEY=831356799639922
CLOUDINARY_API_SECRET=
`;

function ensureCloudinaryEnv() {
  const envPath = path.join(ROOT, '.env');
  const current = fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf8') : '';
  if (/^CLOUDINARY_CLOUD_NAME=/m.test(current)) {
    const secret = current.match(/^CLOUDINARY_API_SECRET=(.*)$/m)?.[1]?.trim();
    console.log(secret ? '  ✔️  .env has the Cloudinary settings' : '  ⚠️  .env: CLOUDINARY_API_SECRET is still empty, paste it in');
    return;
  }
  console.log(`  ${DRY ? 'would add' : '✏️  added'} the Cloudinary settings to .env`);
  if (!DRY) {
    backup('.env');
    fs.writeFileSync(envPath, `${current.replace(/\s*$/, '\n')}${CLOUDINARY_BLOCK}`);
    console.log('  👉 Open .env and paste your API secret after CLOUDINARY_API_SECRET=');
  }
}

console.log(`\n🔨 Adding photo uploads and contract changes to qup-work-api${DRY ? ' (dry run, nothing is changed)' : ''}\n`);
writeFiles();
ensureCloudinaryEnv();

if (!DRY && fs.existsSync(BACKUP)) console.log(`\n📦 Old versions saved in ${path.basename(BACKUP)}/`);
console.log("\n✅ Done. Next: paste CLOUDINARY_API_SECRET into .env, restart the server (npm run dev), then npm run test:flow\n");
